{
  "segment_function": "Definition and phenomenological analysis of the vita activa (labor, work, and action) and its corresponding human conditions.",
  "claims": [
    {
      "claim": "The vita activa is designated by three fundamental human activities: labor, work, and action, each corresponding to a basic condition under which human life on earth is given.",
      "claim_type": "author_position",
      "supporting_excerpt": "With the term vita activa , I propose to designate three fundamental human activities: labor, work, and action. They are fundamental because each corresponds to one of the basic conditions under which life on earth has been given to man.",
      "support_kind": "direct",
      "qualifications": [
        "limited to labor, work, and action"
      ],
      "confidence": 1
    },
    {
      "claim": "Men are fundamentally conditioned beings because everything they contact and all human-made things turn immediately into a condition of their existence.",
      "claim_type": "author_position",
      "supporting_excerpt": "Men are conditioned beings because everything they come in contact with turns immediately into a condition of their existence.",
      "support_kind": "direct",
      "qualifications": [
        "applies to whatever touches or enters into a sustained relationship with human life"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "labor",
      "definition": "The activity corresponding to the biological process of the human body, bound to vital necessities, where the human condition of labor is life itself."
    },
    {
      "term": "work",
      "definition": "The activity corresponding to the unnaturalness of human existence, providing an artificial world of things meant to outlast and transcend individuals, where the human condition of work is worldliness."
    },
    {
      "term": "action",
      "definition": "The only activity going on directly between men without intermediaries, corresponding to the human condition of plurality."
    }
  ],
  "distinctions": [
    {
      "item_a": "labor",
      "item_b": "work",
      "distinction": "Labor corresponds to the biological life process and body, whereas work corresponds to the unnaturalness of human existence and creates an artificial world of things distinct from natural surroundings."
    }
  ],
  "must_not_be_lost": [
    "The connection between labor, work, action and natality versus mortality.",
    "The characterization of plurality as the condition of human action."
  ]
}

